#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxFreeTime(int eventTime, int k, std::vector<int>& startTime, std::vector<int>& endTime) {
        int n = startTime.size();
        std::vector<int> gaps;
        gaps.reserve(n + 1);
        gaps.push_back(startTime[0]);
        for (int i = 1; i < n; ++i) {
            gaps.push_back(startTime[i] - endTime[i - 1]);
        }
        gaps.push_back(eventTime - endTime[n - 1]);

        int window = 0;
        for (int i = 0; i <= k; ++i) window += gaps[i];
        int ans = window;
        for (size_t i = k + 1; i < gaps.size(); ++i) {
            window += gaps[i] - gaps[i - (k + 1)];
            ans = std::max(ans, window);
        }
        return ans;
    }
};

class Solution {
    public int maxFreeTime(int eventTime, int k, int[] startTime, int[] endTime) {
        int n = startTime.length;
        int[] gaps = new int[n + 1];
        gaps[0] = startTime[0];
        for (int i = 1; i < n; i++) {
            gaps[i] = startTime[i] - endTime[i - 1];
        }
        gaps[n] = eventTime - endTime[n - 1];

        int window = 0;
        for (int i = 0; i <= k; i++) window += gaps[i];
        int ans = window;
        for (int i = k + 1; i <= n; i++) {
            window += gaps[i] - gaps[i - (k + 1)];
            ans = Math.max(ans, window);
        }
        return ans;
    }
}

